INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fierce Dragon Godzilla: Metropolis Destruction!!', 'The player takes control of Godzilla in this game. Godzilla goes through towns and forests. Godzilla can step on tanks and fire his atomic breath at soldiers which gives him points. There is a yellow bar that indicates Godzilla''s stamina. Above it, there''s a container that fills up with purple liquid as the game progresses. A newscaster appears in the top-right corner of the screen, delivering news as the action unfolds.' FROM games WHERE igdb_id = 75885 ON CONFLICT (game_id, language_code) DO NOTHING;
