INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: Mystery of Comvoy', 'Transformers: Comvoy no Nazo is a 2D side-scrolling action platformer developed by ISCO and published by TAKARA for the Nintendo Entertainment System (in Japan only) on Decmber 5, 1986. Set in the first-generation Transformers universe, players control Autobot Ultra Magnus as he storms through various Decepticon strongholds to find the whereabouts of Autobot leader Convoy (known worldwide as Optimus Prime).
