INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropical Fish', 'Tropical Fish is a rare New Wide Screen Game & Watch video game released in 1985. The game was never released in Japan. The model number for Tropical Fish is TF-104. In the game, you''ll merge fish from an aquarium into another aquarium via a fishbowl. Overall, the gameplay is very similar to Fire, though perhaps slightly improved. Tropical Fish has also appeared as an unlockable museum game in Game & Watch Gallery 4, albeit in Classic only.' FROM games WHERE igdb_id = 145178 ON CONFLICT (game_id, language_code) DO NOTHING;
