INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('1815', 12354, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/srsqbazlcc9qgxgebjrm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/srpiy1xcnqxewycguo7n.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1815', 'Il s''agit enfin d''un véritable WAR GAME de haut niveau. Basé sur les campagnes napoléoniennes, il reflète fidèlement toutes les possibilités offertes au stratège pour vaincre l''armée ennemie. Le terrain est représenté sur l''écran avec son relief, les villes, les unités des deux armées : infanterie, cavalerie, artillerie, poste de commandement. L''ordinateur sert d''arbitre et gère tous les paramètres. Idéal pour les débutants qui pourront découvrir tout l''art du WAR GAME et pour les joueurs avertis qui pourront s''affronter sur un nouveau plateau de jeu. Enfin ce logiciel offre la possibilité de créer son propre terrain de manœuvre et de le sauvegarder offrant ainsi une multitude de situations ! On peut sauvegarder également une partie en cours. Les joueurs apprécieront un WAR GAME où il n''y a pas des heures de préparation, des manipulations incessantes et des multitudes de petits cartons qui s''envolent au premier courant d''air...' FROM games WHERE igdb_id = 12354 ON CONFLICT (game_id, language_code) DO NOTHING;
