INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conan the Barbarian', 'This game began life as "King Arthur''s Adventure" before Astrovision secured the Conan the Barbarian license. The game was advertised during 1981-1982 but was never released at the time. It later changed name again, this time to Quest For The Orb. Neither Quest for the Orb would see a release as Astrovision/Astrocade hit financial troubles. Eventually a working prototype made its way to Dave Carson Software in 1985 and was released under the Conan the Barbarian name.' FROM games WHERE igdb_id = 172401 ON CONFLICT (game_id, language_code) DO NOTHING;
