INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astroclone', 'Astroclone was published in 1984 by Hewson Consultants. Its working title was Seiclone, but was changed to avoid confusion with Vortex Software''s similar-sounding Cyclone. The game combines shoot ''em up sections with arcade adventure elements that Turner had developed with Avalon (1984) and Dragontorc (1985).' FROM games WHERE igdb_id = 28478 ON CONFLICT (game_id, language_code) DO NOTHING;
