INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Juggernaut', 'An early truck simulation game from Pete Cooke, a developer that later had more success with Tau Ceti and Tower of Babel. In this you have to drive a truck through a maze-style "world" and find the target of your cargo. Then you have to park your truck reverse in a parking bay to reload and refuel it. The game is made with vector graphics.' FROM games WHERE igdb_id = 341138 ON CONFLICT (game_id, language_code) DO NOTHING;
