INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragonskulle', 'Dragon Skulle is an action-adventure game for the Commodore 64 developed and published by Ultimate Play the Game in late 1985. It is a sequel to The Staff of Karnath, Entombed and Blackwyche, and the final title to feature the aristocrat adventurer, Sir Arthur Pendragon. The game was created by brothers Dave and Bob Thomas.' FROM games WHERE igdb_id = 26393 ON CONFLICT (game_id, language_code) DO NOTHING;
