INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quick Draw', 'Quick Draw is a single screen two player shooter where each player stands on either side of the screen as cowboys, and have to try to shoot the other player dead. Both players can move up or down, and in between on the screen are cactus and a wagon that scrolls up the screen. The winner is the player who shoots the other player dead five times.' FROM games WHERE igdb_id = 31468 ON CONFLICT (game_id, language_code) DO NOTHING;
