INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Valley', 'King’s Valley is a platform/maze game from Konami, released for the MSX computer and MS-DOS in 1985. The game plays is like Lode Runner except it takes place in pyramids instead of Egyptian ruins. As an intrepid adventurer, the player''s goal is to collect various gems, while evading angry mummies and other monsters long enough to find the exit to the next level.
