INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('performan', 40405, '1985-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7dmw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11pjw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Performan', 'Performan was Toaplan''s first shooter, and it''s certainly not what one would expect from them, especially when looking at some of their later games. It''s actually a strange, overhead shooter much like Robotron. The star is the titular Performan, a native in a jungle that wears a huge mask, who''s being stalked by a squadron of drill-wielding robots. He must stop them using balls of energy, his ability to dig underground, and bombs that are set up in every level. He can also go into Power Mode by shooting ghosts that randomly appear, which turns him green and invincible for a short time.
