INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rocky Horror Show Computer Game', 'The Rocky Horror Show Computer Game is a 1985 video game for the Commodore 64, Commodore 128, ZX Spectrum and Amstrad CPC created by the CRL Group PLC. The game involved playing as either Brad or Janet and collecting pieces of the Medusa machine scattered around the castle, in order to free your partner from stone and escape the castle before it blasts off. Meanwhile, the other characters in the game can hinder your progress by stealing and hiding your clothes along with what you are carrying. Riff-Raff can kill the player with his laser gun, and Eddie can run the player over with his motorcycle should he thaw out and escape from his freezer.' FROM games WHERE igdb_id = 17274 ON CONFLICT (game_id, language_code) DO NOTHING;
