INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4-D Warriors', 'The game is a horizontal scrolling shooter in which you take control of a jetpack propelled space warrior who travels between parallel universes and worm holes (hence 4-D or 4 dimensions) throughout the game. By flying over the top of the play field, you end up in an alternate universe. You travel back and forth defeating enemies until you reach a boss creature. On some occasions a worm hole will appear in the middle of the play field and you are taken to even stranger worlds.' FROM games WHERE igdb_id = 39453 ON CONFLICT (game_id, language_code) DO NOTHING;
