INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basketball: The Pro Game', 'Basketball: The Pro Game lets you coach your favorite NBA teams, both present and past! Realism and excitement are the trademarks of this strategy-simulation. Talk about dream matchups? How about the ''85 Celtics with Larry Bird against the ''72 Lakers with a young Kareem Abdul Jabbar or the ''84 Sixers with Moses and Dr. J vs. the ''70''s Knicks powered by Willis Reed, Dave DeBusschere and Walt Frazier. The Pro game features the 23 NBA teams from ''86-''87 and more than 125 great teams of the past.' FROM games WHERE igdb_id = 362396 ON CONFLICT (game_id, language_code) DO NOTHING;
