INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Palace', 'You are on a quest to retrieve your dead Father''s crown to help you destroy the evil Ice Queen and remove eternal darkness from your land. You must navigate around her Ice Palace to find the seven pieces of the crown over seven levels to succeed in your quest using objects to solve puzzles. The game is an arcade adventure and contains two screens, the Action Screen or the Adventure Screen.
