INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1985: The Day After', '1984: Escape from Big Brother is a space exploration game set in a post-totalitarian world. Players navigate a spacecraft through underground caverns on four planets, searching for energy pods left behind by the fallen regime. The game features precise rotational controls for maneuvering through tight spaces, and players must use their ship''s tractor beam to collect the crucial energy pods. This challenging adventure combines elements of sci-fi and retrofuturism as humanity rebuilds after liberation from oppressive control.' FROM games WHERE igdb_id = 26150 ON CONFLICT (game_id, language_code) DO NOTHING;
