INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aoki Ookami to Shiroki Mejika', 'Aoki Ookami to Shiroki Mejika was first released in 1985. Players become Temujin, who has just become 20, and fight to unify the Mongolian plains. After uniting the plains, you are renamed Genghis Khan and proceed to conquer Eurasia. Grow rich and conquer all you come across.' FROM games WHERE igdb_id = 30922 ON CONFLICT (game_id, language_code) DO NOTHING;
