INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brain Breaker', 'Brain Breaker is an epic open-world platform-adventure for the Sharp X1 Japanese home computer. It was an early Metroidvania-style game, predating both Metroid and Castlevania. It was designed by Hiroshi Ishikawa and published by Enix in 1985.' FROM games WHERE igdb_id = 70164 ON CONFLICT (game_id, language_code) DO NOTHING;
