INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Othello', 'Othello board game for BBC Micro. At the start of each game the players place four counters at the center of the board. Thereafter the players take it in turns to place a counter with their own colour face up on an empty square in such a way there are at least one counter of the opposite colour sandwiched between it and another of the player''s colour in either a horizontal, vertical or diagonal direction.' FROM games WHERE igdb_id = 134419 ON CONFLICT (game_id, language_code) DO NOTHING;
