INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gimme-a-break', 39732, '1985-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwnnd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gimme a Break', 'Gimme a Break is a cue sports arcade game which was released by Bally and Sente in 1985; it was the first of the second batch of games to run on that company''s SAC-I hardware, and the player must use a singular button to position the cue ball, with a trackball to control it during each shot. In a two-player game, one player must aim for the solid-coloured balls (1 to 7), while the other must aim for the white ones with a coloured stripe across them (9 to 15) - and in a one-player game there will also be bonus rounds where the player must pot bonus balls to earn extra shots. If players should pot three or more balls, with a single shot, they''ll get treated to a slow-motion "action replay" of it; it is also worth noting that if a certain dip switch is set to "on", this game will show pictures of children who were missing at the time in its attract mode (and this also applies to that other Bally/Sente game for 1985, Mini Golf).' FROM games WHERE igdb_id = 39732 ON CONFLICT (game_id, language_code) DO NOTHING;
