INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Alien Island: 3D-Version', 'The Alien Island: 3D-Version is a first-person shooter that takes place on a small island inhabited by alien monsters. Your mission is to kill the aliens, find the treasure, and take the boat back. The world around you is presented in a pseudo-three-dimensional style, with a first-person view. You are armed with a pistol to shoot enemies. In addition to this, you have a compass and a map of the island in our inventory.' FROM games WHERE igdb_id = 174636 ON CONFLICT (game_id, language_code) DO NOTHING;
