INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('batten-tanuki-no-daibouken', 47548, '1985-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvywd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batten Tanuki no Daibouken', 'Once upon a time, there was a village where only animals lived. One day, the Count Wolf came to this village, cast a spell on the animals, and took them all to the wolf castle. The only one who survived was an old lady rabbit who was sick. At that time, a Tanuki came to this village. When he heard about the situation from the old rabbit, he bravely went to the wolf castle to save the villagers from the magic alone, even though he was training in kung fu.' FROM games WHERE igdb_id = 47548 ON CONFLICT (game_id, language_code) DO NOTHING;
