INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Avenger', 'Players assume the role of an angry cop on a wild ride as he pursues a gang of bikers who killed his wife. Players need to race through oncoming traffic, squeeze between trucks, trash motorcycles and steer through lots of explosions. The only thing needed are quick reflexes to follow the instructions on the screen (with an increasing difficulty) in order to keep the animation going.' FROM games WHERE igdb_id = 93049 ON CONFLICT (game_id, language_code) DO NOTHING;
