INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Jack', 'Black Jack is a Multi Screen Game & Watch game released in 1985 by Nintendo. A Pocketsize version was also released. The game is simply Black Jack on an LCD screen. The game is very different from the standard Game & Watch games. If your cards amount to a combined number of 21, then you win the game. Black Jack is the last Game & Watch video game to be released in Japan. All games released after Black Jack were released only in other countries, despite being made in Japan.' FROM games WHERE igdb_id = 145220 ON CONFLICT (game_id, language_code) DO NOTHING;
