INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galactic-warriors', 40036, '1985-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co965w.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Warriors', 'The game is controlled with an 8-way joystick and three buttons: the attack button, the guard button, and the weapon selection button. There are six stages, each with different themes and environmental effects based on gravity. Some other features introduced in Galactic Warriors that were used in later fighting games include block damage, air-blocking, the ability to shoot/throw projectiles, the ability to execute multiple attacks while airborne, a modern health bar (as opposed to a health meter with notches like in Capcom''s Mega Man series that made their debut two years later), the ability to switch between armed and unarmed and attacks of varying levels of strength.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40036 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
