INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('balance-of-power-geopolitics-in-the-nuclear-age', 11935, '1985-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x6aw08jh2ylq5uya9ujp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s31n9av7suzli0061i6h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Balance of Power: Geopolitics in the Nuclear Age', 'It has been more than forty years since the first nuclear bomb exploded. In that time, the shape of the world has changed dramatically. The power to destroy civilization rests in the hands of the superpowers and now, as either the president of the U.S. or as the General Secretary of the U.S.S.R., you have total responsibility for your nation''s course. To succeed, you must enhance your country''s prestige without infringing too much on your adversary''s interests. If you play the isolationist, you will find yourself alone in a world dominated by your opponent. If you are too aggressive, you could unleash the war that annihilates humankind- and both sides lose. 
