INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Repton 2', 'Repton 2 follows the same basic ''Boulderdash'' puzzle style gameplay as its predecessor, and also adds a few new features to freshen things up: meteors, which would fall from the sky and kill upon contact, skulls, static objects that would kill the player if they were careless enough to walk into it, and the fast-moving spirits which would journey around the map hugging walls and objects and veering to any left-angles they came across.' FROM games WHERE igdb_id = 37073 ON CONFLICT (game_id, language_code) DO NOTHING;
