INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Payload', 'In this driving game, players control an independent Japanese truck driver responsible for delivering cargo and earning payment upon successful completion. Strategic management is key as players select contracts, aim for timely deliveries to avoid commission deductions, and navigate challenges such as fines for overloading, speeding, or running red lights. Expenses for fuel and repairs add to the game''s complexity.' FROM games WHERE igdb_id = 41787 ON CONFLICT (game_id, language_code) DO NOTHING;
