INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Sub', 'Turbo Sub released in 1985 as an arcade shooter game by Entertainment Sciences. Then later in 1991 for the Atari Lynx. The arcade version was a one player game set in the future where you control a submersible ship against a horde of aliens. The Atari Lynx version is the same but can be played with two players and tells us the story is set in the 28th century on Earth. The planet has been invaded and the goal of the game is that the player must destroy all the aliens.' FROM games WHERE igdb_id = 40866 ON CONFLICT (game_id, language_code) DO NOTHING;
