INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crimson Crown', 'The Crimson Crown continues the Transylvania series as players guide Princess Sabrina and Crown Prince Erik in their quest to recover a powerful royal artifact stolen after King John''s death. Players must prevent Vampire Lord Drakul from using the crown''s power to seize the throne, utilizing each companion''s unique abilities - Sabrina''s magic and Erik''s royal birthright. The adventure unfolds across familiar and new locations, from ancient forests to the Wizard''s castle, where players interact with various beings including griffins, witches, and riddle-posing trolls, while heeding advice from a mysterious Sage.' FROM games WHERE igdb_id = 15532 ON CONFLICT (game_id, language_code) DO NOTHING;
