INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Fox: Yuki no Maou-hen', 'Harry Fox: Yuki no Maou-hen (“Chapter of the Demonic Snow Lord”) is a direct sequel of Harry Fox. Winter has come and dumped a ton of snow on the land. Unfortunately the mama fox perished while out hunting, but her child was nursed back to health thanks to a local girl named Mari. Once the snow cleared, they sought her out again, before learning that she was actually kidnapped by an evil demon (!!), so it’s up to the little fox to save her.' FROM games WHERE igdb_id = 67547 ON CONFLICT (game_id, language_code) DO NOTHING;
