INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer', 'World Soccer, known as Great Soccer in the US and Super Futebol in Brazil, is a sports game developed and published by Sega for the Sega Master System. The game was rereleased in Japan a year later under the name Sports Pad Soccer, which was bundled with the Sega Sports Pad.' FROM games WHERE igdb_id = 12893 ON CONFLICT (game_id, language_code) DO NOTHING;
