INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Set Willy II', 'Jet Set Willy II: The Final Frontier is a platform game released in 1985 by Software Projects for a variety of 8-bit home computers. It was the only official sequel to Jet Set Willy, one of the most successful and popular home computer games ever released. Officially, Jet Set Willy II: The Final Frontier is the last of the Miner Willy series, although numerous unofficial sequels, remakes, homages and updates have been released, even up to this day.' FROM games WHERE igdb_id = 8171 ON CONFLICT (game_id, language_code) DO NOTHING;
