INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Attack', 'A Space Invaders/Galaxian clone written by John P. Shay and published by Solar Software for the Commodore 16 and 4 Plus. In Alien Attack you move a spacecraft left or right at the bottom of the screen, blasting aliens in formation above. You must avoid the bombs that they drop as well as avoid any aliens that swoop downwards or you lose one of three lives if you touch an alien or its bombs. Once you clear the screen, you face another wave of aliens.' FROM games WHERE igdb_id = 13945 ON CONFLICT (game_id, language_code) DO NOTHING;
