INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major Blink: Berks 2', 'In this action game written by Jon Williams the player takes the role of Major Blink, the creator of the Berks, who has now become a painter. All blocks must be painted from all sides by the Major while homing drones must be avoided and bears, who try to repaint the blocks, must be shot.' FROM games WHERE igdb_id = 60525 ON CONFLICT (game_id, language_code) DO NOTHING;
